// BusinessServiceServer is the server API for BusinessService service.
// All implementations must embed UnimplementedBusinessServiceServer
// for forward compatibility.
type BusinessServiceServer interface {
	// Business Profile
	CreateBusinessProfile(context.Context, *CreateBusinessProfileRequest) (*CreateBusinessProfileResponse, error)
	UpdateBusinessProfile(context.Context, *UpdateBusinessProfileRequest) (*UpdateBusinessProfileResponse, error)
	GetBusinessProfile(context.Context, *GetBusinessProfileRequest) (*GetBusinessProfileResponse, error)
	// Product Catalog (legacy)
	CreateCatalog(context.Context, *CreateCatalogRequest) (*CreateCatalogResponse, error)
	AddProduct(context.Context, *AddProductRequest) (*AddProductResponse, error)
	UpdateProduct(context.Context, *UpdateProductRequest) (*UpdateProductResponse, error)
	ListProducts(context.Context, *ListProductsRequest) (*ListProductsResponse, error)
	// Marketplace Products
	CreateMarketplaceProduct(context.Context, *CreateMarketplaceProductRequest) (*CreateMarketplaceProductResponse, error)
	UpdateMarketplaceProduct(context.Context, *UpdateMarketplaceProductRequest) (*UpdateMarketplaceProductResponse, error)
	DeleteMarketplaceProduct(context.Context, *DeleteMarketplaceProductRequest) (*DeleteMarketplaceProductResponse, error)
	GetMarketplaceProduct(context.Context, *GetMarketplaceProductRequest) (*GetMarketplaceProductResponse, error)
	ListBusinessProducts(context.Context, *ListBusinessProductsRequest) (*ListBusinessProductsResponse, error)
	ListMarketplaceProducts(context.Context, *ListMarketplaceProductsRequest) (*ListMarketplaceProductsResponse, error)
	// Product Variants
	CreateProductVariant(context.Context, *CreateProductVariantRequest) (*CreateProductVariantResponse, error)
	ListProductVariants(context.Context, *ListProductVariantsRequest) (*ListProductVariantsResponse, error)
	UpdateProductVariant(context.Context, *UpdateProductVariantRequest) (*UpdateProductVariantResponse, error)
	DeleteProductVariant(context.Context, *DeleteProductVariantRequest) (*DeleteProductVariantResponse, error)
	// Categories
	ListCategories(context.Context, *ListCategoriesRequest) (*ListCategoriesResponse, error)
	// Store (public)
	GetStore(context.Context, *GetStoreRequest) (*GetStoreResponse, error)
	// Engagement
	TrackProductView(context.Context, *TrackProductViewRequest) (*TrackProductViewResponse, error)
	CreateReview(context.Context, *CreateReviewRequest) (*CreateReviewResponse, error)
	ListReviews(context.Context, *ListReviewsRequest) (*ListReviewsResponse, error)
	// Appointments
	CreateAppointmentSlot(context.Context, *CreateAppointmentSlotRequest) (*CreateAppointmentSlotResponse, error)
	BookAppointment(context.Context, *BookAppointmentRequest) (*BookAppointmentResponse, error)
	ListAppointments(context.Context, *ListAppointmentsRequest) (*ListAppointmentsResponse, error)
	// Auto-Reply
	SetAutoReply(context.Context, *SetAutoReplyRequest) (*SetAutoReplyResponse, error)
	GetAutoReplies(context.Context, *GetAutoRepliesRequest) (*GetAutoRepliesResponse, error)
	// Customer Queue
	EnqueueCustomer(context.Context, *EnqueueCustomerRequest) (*EnqueueCustomerResponse, error)
	DequeueCustomer(context.Context, *DequeueCustomerRequest) (*DequeueCustomerResponse, error)
	GetQueuePosition(context.Context, *GetQueuePositionRequest) (*GetQueuePositionResponse, error)
	// Cart
	AddToCart(context.Context, *AddToCartRequest) (*AddToCartResponse, error)
	GetCart(context.Context, *GetCartRequest) (*GetCartResponse, error)
	UpdateCartItem(context.Context, *UpdateCartItemRequest) (*UpdateCartItemResponse, error)
	RemoveFromCart(context.Context, *RemoveFromCartRequest) (*RemoveFromCartResponse, error)
	ClearCart(context.Context, *ClearCartRequest) (*ClearCartResponse, error)
	// Orders
	CreateOrders(context.Context, *CreateOrdersRequest) (*CreateOrdersResponse, error)
	GetOrder(context.Context, *GetOrderRequest) (*GetOrderResponse, error)
	ListBuyerOrders(context.Context, *ListBuyerOrdersRequest) (*ListBuyerOrdersResponse, error)
	ListSellerOrders(context.Context, *ListSellerOrdersRequest) (*ListSellerOrdersResponse, error)
	UpdateOrderStatus(context.Context, *UpdateOrderStatusRequest) (*UpdateOrderStatusResponse, error)
	UpdateOrderTracking(context.Context, *UpdateOrderTrackingRequest) (*UpdateOrderTrackingResponse, error)
	// Coupons
	CreateCoupon(context.Context, *CreateCouponRequest) (*CreateCouponResponse, error)
	ListBusinessCoupons(context.Context, *ListBusinessCouponsRequest) (*ListBusinessCouponsResponse, error)
	ValidateCoupon(context.Context, *ValidateCouponRequest) (*ValidateCouponResponse, error)
	// Wishlist
	ToggleWishlist(context.Context, *ToggleWishlistRequest) (*ToggleWishlistResponse, error)
	GetWishlist(context.Context, *GetWishlistRequest) (*GetWishlistResponse, error)
	// Product Q&A
	AskProductQuestion(context.Context, *AskProductQuestionRequest) (*AskProductQuestionResponse, error)
	AnswerProductQuestion(context.Context, *AnswerProductQuestionRequest) (*AnswerProductQuestionResponse, error)
	GetProductQuestions(context.Context, *GetProductQuestionsRequest) (*GetProductQuestionsResponse, error)
	FlagProductQuestion(context.Context, *FlagProductQuestionRequest) (*FlagProductQuestionResponse, error)
	ModerateProductQuestion(context.Context, *ModerateProductQuestionRequest) (*ModerateProductQuestionResponse, error)
	// Order Status Workflow
	TransitionOrderStatus(context.Context, *TransitionOrderStatusRequest) (*TransitionOrderStatusResponse, error)
	GetOrderStatusHistory(context.Context, *GetOrderStatusHistoryRequest) (*GetOrderStatusHistoryResponse, error)
	// Refunds
	CreateRefund(context.Context, *CreateRefundRequest) (*CreateRefundResponse, error)
	ProcessRefund(context.Context, *ProcessRefundRequest) (*ProcessRefundResponse, error)
	ListRefunds(context.Context, *ListRefundsRequest) (*ListRefundsResponse, error)
	// Order Modifications
	CreateOrderModification(context.Context, *CreateOrderModificationRequest) (*CreateOrderModificationResponse, error)
	ProcessOrderModification(context.Context, *ProcessOrderModificationRequest) (*ProcessOrderModificationResponse, error)
	ListOrderModifications(context.Context, *ListOrderModificationsRequest) (*ListOrderModificationsResponse, error)
	mustEmbedUnimplementedBusinessServiceServer()
}

